-- T4 — Capability registry & goal templates (backend/T4-capability-registry.md).
-- Config tables: what can be done (capabilities), who does it (providers = catalogue items),
-- and each goal as an ordered template of capabilities. A new goal = new rows, zero code.
-- Rows come from web/src/backend/fixtures/t4-rules.ts via supabase/seed/capabilities.sql
-- (generated by scripts/registry/seed.ts). Item names and partners are not copied here:
-- the backend joins capability_providers.source_row to ecosystem_items / partners.

create table public.capabilities (
  code text primary key,
  label text not null,
  ecosystem text not null,
  what_it_solves text not null,
  required_data text[] not null default '{}',
  output text not null
);

create table public.capability_providers (
  capability_code text not null references public.capabilities (code) on delete cascade,
  source_row int not null references public.ecosystem_items (source_row),
  lead_time_days int not null check (lead_time_days >= 0),
  cost_eur numeric(12, 2) check (cost_eur >= 0),
  priority int not null,
  estimates jsonb not null default '{}'::jsonb,   -- shape of the TS `Estimates` type; illustrative figures
  primary key (capability_code, source_row)
);
create index capability_providers_source_row_idx on public.capability_providers (source_row);

create table public.goal_templates (
  goal_type text primary key,
  label text not null,
  default_constraints jsonb not null default '{}'::jsonb,
  outcome text not null
);

create table public.template_steps (
  goal_type text not null references public.goal_templates (goal_type) on delete cascade,
  capability_code text not null references public.capabilities (code),
  chapter text not null,
  position int not null check (position > 0),
  depends_on text[] not null default '{}',        -- capability codes of the same template
  condition jsonb,                                -- TS `Condition`, evaluated against { ctx, goal }
  why text not null,                              -- may contain {placeholders}
  optional boolean not null default false,
  primary key (goal_type, capability_code),
  unique (goal_type, position)
);
create index template_steps_capability_code_idx on public.template_steps (capability_code);

-- Config pattern (same as the catalogue): readable by anyone, written only by migrations / the secret key.
alter table public.capabilities enable row level security;
alter table public.capability_providers enable row level security;
alter table public.goal_templates enable row level security;
alter table public.template_steps enable row level security;

create policy "registry is readable" on public.capabilities
  for select to anon, authenticated using (true);
create policy "registry is readable" on public.capability_providers
  for select to anon, authenticated using (true);
create policy "registry is readable" on public.goal_templates
  for select to anon, authenticated using (true);
create policy "registry is readable" on public.template_steps
  for select to anon, authenticated using (true);

revoke insert, update, delete, truncate on
  public.capabilities, public.capability_providers, public.goal_templates, public.template_steps
  from anon, authenticated;
